    # Stage 3: G = E * F (G[i, l] = sum_j E[i, j] * F[j, l])
    # ---------------------------------------------------

    # 3D blocking in (i, l, j).
    block(i, I_G, TI)
    block(l, L_G, TL)
    block(j, J_G, TJ)

    hoist(I_G)
    hoist(L_G)
    hoist(J_G)

