        ACCUM_SUM(r, q, s, p) -> STORE_A(r, q, p)

optimization:
    # High-level algorithmic optimization (already reflected in the computation):
    #
    #   - Original kernel (in the provided code) conceptually does:
    #        for r, q:
    #          for p:
    #            sum[p] = 0
    #            for s:
    #              sum[p] += A[r, q, s] * C4[s, p]
    #          for p:
    #            A[r, q, p] = sum[p]
    #
    #     Each A[r, q, s] is reloaded NP times (once per p), and C4[s, p] is
    #     accessed with a large stride in memory.
    #
    #   - The model above uses a "plane-wise" accumulation order:
    #        for r, q:
    #          for p:          sum[p] = 0
    #          for s:
    #            a_rqs = A[r, q, s]
    #            for p:        sum[p] += a_rqs * C4[s, p]
    #          for p:          A[r, q, p] = sum[p]
    #
    #     This:
    #       * loads A[r, q, s] once and reuses it across all p,
    #       * walks C4[s, p] row-wise with p as the innermost index (contiguous),
    #       * keeps writes to A[r, q, p] contiguous in p.
    #     Thus, it drastically reduces memory traffic on A and improves
    #     locality for both C4 and A.

    # 1) Parallelize across independent (r, q) planes.
    #
    #    All computations for different (r, q) pairs are independent once sum[p]
    #    is made thread-private. We therefore:
    #
    #      - tile r and q to form coarse-grain work units (R, Q),
    #      - hoist these tiles to the outermost loops,
    #      - parallelize over R (and implicitly over Q inside each thread).
    #
    #    sum[p] is **privatized per parallel worker** (stack or thread-local
    #    allocation), which is feasible because it has size O(NP) << O(NR*NQ*NP).
    block(r, R, T_R)
    block(q, Q, T_Q)
    hoist(R)              # outermost: tiles of r
    hoist(Q)              # next: tiles of q inside each tile of r
    parallelize(R)        # distribute (R, Q) tiles across threads; privatize sum[p]

    # 2) Tile and vectorize along p (fastest-varying dimension).
    #
    #    The innermost numeric work for each (r, q, s) is:
    #       for p: sum[p] += a_rqs * C4[s, p]
    #
    #    This is a SAXPY-like operation over contiguous segments of both sum[p]
    #    and C4[s, p], ideal for SIMD. We:
    #
    #      - tile p into P (coarse tiles) and inner p (fine index),
    #      - hoist P outside the s-loop so that we reuse sum[p] and C4 tiles
    #        in cache across s,
    #      - vectorize over the inner p dimension,
    #      - optionally unroll that dimension to reduce loop overhead.
    block(p, P, T_P)
    hoist(P)              # loop nest becomes: for r, q, P, (INIT/ACCUM/STORE over inner p)
    vectorize(p, V_P)     # map inner p-loop to SIMD lanes (aligned contiguous access)
    unroll(p, U_P)        # optional further unrolling for ILP; chosen as a small multiple of V_P

    # 3) Tile s for cache reuse of A and C4 rows.
    #
    #    For each (r, q), the working set during accumulation is:
    #      - one row A[r, q, *] of length NP,
    #      - multiple rows C4[s, *] and the buffer sum[*].
    #
    #    Tiling s keeps the active subset of C4[s, *] small and improves temporal
    #    locality as we repeatedly multiply the same A[r, q, s] by a contiguous
    #    block of C4[s, p] and update a contiguous block of sum[p].
    block(s, S, T_S)
    hoist(S)              # loop order inside (R, Q, P) tiles: for S, for s in S-tile

    # 4) Resulting preferred execution order (schematic, respecting dependencies):
    #
    #    for R in tiles of r (parallelized):
    #      for Q in tiles of q:
    #        for r in R-tile:
    #          for q in Q-tile:
    #            for P in tiles of p:
    #              # INIT: zero sum over inner p in this tile
    #              for p in P-tile (vectorized, unrolled):
    #                INIT_SUM: sum[p] = 0
    #
    #              # ACCUM: reduce over S and inner s, updating sum[p]
    #              for S in tiles of s:
    #                for s in S-tile:
    #                  let a_rqs = A[r, q, s]              # scalar reused across p
    #                  for p in P-tile (vectorized, unrolled):
    #                    ACCUM_SUM: sum[p] += a_rqs * C4[s, p]
    #
    #              # STORE: write back contiguous block of A[r, q, p]
    #              for p in P-tile (vectorized, unrolled):
    #                STORE_A: A[r, q, p] = sum[p]
    #
    #    This schedule:
    #      - preserves all dependencies in the original kernel,
    #      - reduces reloads of A[r, q, s] from O(NP^2) to O(NP) per (r, q),
    #      - makes all accesses to C4 and A along p streaming and SIMD-friendly,
    #      - exposes coarse-grained parallelism in r (and q) for multi-core CPUs,
    #      - keeps the extra memory usage within ≈ O(NP) per thread via
    #        a privatized sum[p], well below the 50% overhead budget.
--- END OF MODEL: doitgen-05 ---

--- START OF SOURCE: doitgen.cpp ---
#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/structures_extended.hpp>
#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions (DATA_TYPE, NR, NQ, NP, ...)
#include "defines.hpp"

// include benchmark-specific definitions (NR, NQ, NP, etc.)
#include "doitgen.hpp"

using num_t = DATA_TYPE;

namespace {

// dimension prototypes
constexpr auto r_vec = noarr::vector<'r'>(); // corresponds to C index r (0..NR-1)
constexpr auto q_vec = noarr::vector<'q'>(); // corresponds to C index q (0..NQ-1)
constexpr auto p_vec = noarr::vector<'p'>(); // corresponds to C index p (0..NP-1)
constexpr auto s_vec = noarr::vector<'s'>(); // corresponds to C index s (0..NP-1)

// layouts (match C memory layout: last index varies fastest)
constexpr auto A_layout  = p_vec ^ q_vec ^ r_vec; // A[r][q][p]
constexpr auto C4_layout = p_vec ^ s_vec;         // C4[s][p]
constexpr auto sum_layout = p_vec;                // sum[p]

// initialization function
void init_array(auto A, auto C4) {
	using namespace noarr;

	// A[r][q][p] = ((r*q + p) % np) / np;
	traverser(A).for_each([=](auto state) {
		auto [r, q, p] = get_indices<'r', 'q', 'p'>(state);
		auto np_len = A | get_length<'p'>();

		A[state] = static_cast<num_t>(( (r * q + p) % np_len ))
			/ static_cast<num_t>(np_len);
	});

	// C4[s][p] = (s*p % np) / np;
	traverser(C4).for_each([=](auto state) {
		auto [s, p] = get_indices<'s', 'p'>(state);
		auto np_len = C4 | get_length<'p'>();

		C4[state] = static_cast<num_t>(( (s * p) % np_len ))
			/ static_cast<num_t>(np_len);
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(auto A, auto C4, auto sum) {
	using namespace noarr;

	// C kernel:
	// for (r)
	//   for (q) {
	//     for (p) {
	//       sum[p] = 0;
	//       for (s)
	//         sum[p] += A[r][q][s] * C4[s][p];
	//     }
	//     for (p)
	//       A[r][q][p] = sum[p];
	//   }

#pragma scop
	traverser(A, sum).template for_dims<'r', 'q'>([=](auto trav_rq) {

		// First loop over p: compute sum[p] = Σ_s A[r][q][s] * C4[s][p]
		trav_rq.template for_dims<'p'>([=](auto trav_rqp) {
			auto state_rqp = trav_rqp.state(); // contains indices r, q, p

			// sum[p] = 0.0;
			sum[state_rqp] = static_cast<num_t>(0);

			// extract indices r, q, p
			auto r_idx = get_index<'r'>(state_rqp);
			auto q_idx = get_index<'q'>(state_rqp);
			auto p_idx = get_index<'p'>(state_rqp);

			// view of C4 with fixed column p_idx: C4[s][p_idx]
			auto C4_p = C4 ^ noarr::fix<'p'>(p_idx);

			// inner loop over s
			noarr::traverser(C4_p).for_each([=](auto state_s) {
				auto s_idx = get_index<'s'>(state_s);

				// A[r][q][s]
				auto state_rqs = noarr::idx<'r', 'q', 'p'>(r_idx, q_idx, s_idx);

				// sum[p] += A[r][q][s] * C4[s][p]
				sum[state_rqp] += A[state_rqs] * C4_p[state_s];
			});
		});

		// Second loop over p: A[r][q][p] = sum[p]
		trav_rq.template for_dims<'p'>([=](auto trav_rqp) {
			auto state_rqp = trav_rqp.state();
			A[state_rqp] = sum[state_rqp];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t nr = NR;
	std::size_t nq = NQ;
	std::size_t np = NP;

	// allocate data (bags)
	auto A = noarr::make_bag(
		noarr::scalar<num_t>()
		^ A_layout
		^ noarr::set_length<'r'>(nr)
		^ noarr::set_length<'q'>(nq)
		^ noarr::set_length<'p'>(np));

	auto C4 = noarr::make_bag(
		noarr::scalar<num_t>()
		^ C4_layout
		^ noarr::set_length<'s'>(np)
		^ noarr::set_length<'p'>(np));

	auto sum = noarr::make_bag(
		noarr::scalar<num_t>()
		^ sum_layout
		^ noarr::set_length<'p'>(np));

	// initialize arrays
	init_array(A.get_ref(), C4.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_doitgen(A.get_ref(), C4.get_ref(), sum.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// optionally print output (to prevent DCE and to check correctness)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'r' for a more natural outer dimension in the dump
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'r'>());
	}

	// print elapsed time in seconds
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
