    # keeps the extra memory footprint well below 50% of the original
    # (which had an explicit z[0..N-1] array).
    reuse_stack_buffers(size_per_thread << N)  # conceptual: reuse small per-thread buffers; no semantic change
--- END OF MODEL: durbin-02 ---

--- START OF MODEL: durbin-03 ---
domain:
    i: dim in [0, N)          # main data dimension
    k: loop in [0, N)         # Durbin recursion step (not an array dimension)

data:
    # r and y are contiguous 1D arrays over i
    r[i]: in    num_t = i     # r[i] stored at offset i
    y[i]: inout num_t = i     # y[i] stored at offset i

    # z is a temporary 1D buffer with the same layout as y, size N.
    # It is only needed by the baseline formulation and can later be eliminated.
    z[i]: local num_t = i

parameters:
    N: int                     # problem size (length of r and y)
    alpha: num_t               # Durbin scalar
    beta: num_t                # Durbin scalar
    sum: num_t                 # inner reduction accumulator

computation:
    # Initialization kernel (matches init_array): r[i] = N + 1 - i
    INIT_R:
        for i:
            r[i] = (num_t)(N + 1 - i)

    DURBIN:
        # y[0] = -r[0]; beta = 1.0; alpha = -r[0];
        y[0] = -r[0]
        beta = 1
        alpha = -r[0]

        # Main Durbin recursion: outer loop over k is inherently sequential
        K_LOOP:
            for k in seq(1, N):
                UPDATE_BETA:
                    beta = (1 - alpha * alpha) * beta

                SUM_LOOP:
                    sum = 0
                    # sum = sum_{i=0}^{k-1} r[k-1-i] * y[i]
                    sum = sum(i in [0, k), r[k - 1 - i] * y[i])

                UPDATE_ALPHA:
                    alpha = -(r[k] + sum) / beta

                Z_WRITE:
                    # for (i = 0; i < k; i++) z[i] = y[i] + alpha * y[k - i - 1];
                    for i in [0, k):
                        z[i] = y[i] + alpha * y[k - 1 - i]

                Y_FROM_Z:
                    # for (i = 0; i < k; i++) y[i] = z[i];
                    for i in [0, k):
                        y[i] = z[i]

                SET_YK:
                    # y[k] = alpha;
                    y[k] = alpha

optimization:
    # r, y, z are already contiguous; keep this layout.
    # Align to cache-line / SIMD width for better vector loads/stores.
    align(r, 64)
    align(y, 64)
    align(z, 64)

    # 1) Improve inner reduction locality and vectorization
    #    SUM_LOOP currently uses:
    #         sum = sum(i in [0, k), r[k-1-i] * y[i])
    #    Algebraically we can substitute j = k-1-i:
    #         sum = sum(j in [0, k), r[j] * y[k-1-j])
    #    which reads r[0..k-1] in increasing order (streaming).
    rewrite(SUM_LOOP):
        use iterator j in [0, k) with body:
            sum += r[j] * y[k - 1 - j]

    #    Expose SIMD/ILP in this reduction. VF_SUM and UF_SUM are tunable
    #    constants (e.g., VF_SUM ∈ {4, 8, 16}, UF_SUM ∈ {1, 2, 4}).
    vectorize(j, VF_SUM) in SUM_LOOP
    unroll(j, UF_SUM) in SUM_LOOP

    # 2) SIMD on the two y/z update loops in the baseline
    #    (before we fuse them and remove z)
    vectorize(i, VF_ZWRITE) in Z_WRITE
    unroll(i, UF_ZWRITE) in Z_WRITE

    vectorize(i, VF_YCOPY) in Y_FROM_Z
    unroll(i, UF_YCOPY) in Y_FROM_Z

    # 3) Fuse Z_WRITE and Y_FROM_Z and eliminate the temporary array z
    #
    #    Semantics of the two loops:
    #      for i in [0, k):
    #          z[i]   = y[i] + alpha * y[k-1-i]
    #      for i in [0, k):
    #          y[i]   = z[i]
    #
    #    Combining them, for each i we want:
    #          y_new[i] = y_old[i] + alpha * y_old[k-1-i]
    #
    #    We can implement this in-place (without z) by updating symmetric
    #    pairs (i, j) with j = k-1-i, using two scalar temporaries yi, yj:
    #
    #      for i in [0, k):
    #          j = k - 1 - i
    #          if i < j:
    #              yi = y[i]; yj = y[j]
    #              y[i] = yi + alpha * yj
    #              y[j] = yj + alpha * yi
    #          elif i == j:
    #              # middle element when k is odd
    #              y[i] = y[i] * (1 + alpha)
    #          else:
    #              # pair (j, i) already updated when j < i
    #              continue
    #
    #    This produces exactly the same y as Z_WRITE + Y_FROM_Z (all reads of
    #    y on the right-hand side use the pre-update values). It removes all
    #    accesses to z and halves the number of array reads/writes in this
    #    phase, reducing memory traffic and improving cache/SIMD efficiency.
    fuse(Z_WRITE, Y_FROM_Z) -> Y_INPLACE_UPDATE
    eliminate_array(z)
    replace(Y_INPLACE_UPDATE body as above)

    #    The in-place pairwise update over i is still vectorizable. A
    #    practical strategy is to vectorize only the region where i < j,
    #    and handle the (optional) center element (i == j) with a scalar
    #    instruction when k is odd.
    vectorize(i, VF_YINPLACE) in Y_INPLACE_UPDATE
    unroll(i, UF_YINPLACE) in Y_INPLACE_UPDATE

    # 4) Optional intra-k parallelism
    #    The outer loop K_LOOP must remain sequential (alpha, beta, y[k]
    #    form a recurrence across k). However, for each fixed k:
    #      - SUM_LOOP is a pure reduction over j
    #      - Y_INPLACE_UPDATE updates disjoint (i, j) pairs
    #    so their iterations can be parallelized.
    #
    #    Implement SUM_LOOP as a parallel reduction over j, and
    #    Y_INPLACE_UPDATE as a parallel-for over i (using appropriate
    #    synchronization/barriers between SUM_LOOP, UPDATE_ALPHA and
    #    Y_INPLACE_UPDATE).
    parallelize(j) in SUM_LOOP      # parallel reduction over j
    parallelize(i) in Y_INPLACE_UPDATE
--- END OF MODEL: durbin-03 ---

--- START OF MODEL: durbin-04 ---
domain:
    # i: index into the 1D Toeplitz / coefficient vectors
    i: dim in [0, N)
    # k: outer Durbin recursion index
    k: dim in [0, N)
    # p: auxiliary index for pairwise in‑place updates of y[0..k-1]
    p: dim in [0, N)

data:
    # r: input reflection / autocorrelation coefficients, read‑only in kernel
    # Layout: contiguous 1D, element i at offset i
    r[i]: in num_t = (i) -> i

    # y: solution / prediction coefficients, updated in place
    # Layout: contiguous 1D, element i at offset i
    y[i]: inout num_t = (i) -> i

parameters:
    # N is the problem size (length of r and y); matches define N and length<'i'>
    N: size_t
    # Scalar temporaries in the kernel
    alpha: num_t
    beta: num_t
    sum:  num_t

computation:
    # Initialization corresponding to:
    #   y[0] = -r[0];
    #   beta = 1.0;
    #   alpha = -r[0];
    init:
        y[0] = -r[0]
        beta = 1.0
        alpha = -r[0]

    # Main Durbin recursion:
    #   for k = 1..N-1:
    #     beta = (1 - alpha^2)*beta
    #     sum  = sum_{i=0..k-1} r[k-i-1] * y[i]
    #     alpha = -(r[k] + sum)/beta
    #     y[0..k-1] <- y[0..k-1] + alpha * reversed(y[0..k-1])
    #     y[k] = alpha
    #
    # The k loop must be sequential because each iteration depends on the full
    # contents of y[0..k-1] produced by the previous iteration.
    durbin:
        for k in seq(1, N):
            # beta = (1 - alpha * alpha) * beta;
            beta = (1.0 - alpha * alpha) * beta

            # sum = 0.0; for (i = 0; i < k; i++) sum += r[k - i - 1] * y[i];
            # Expressed as an explicit reduction to expose parallelism:
            sum = sum(i in [0, k), r[k - i - 1] * y[i])

            # alpha = - (r[k] + sum) / beta;
            alpha = -(r[k] + sum) / beta

            # Original code:
            #   for (i = 0; i < k; i++) z[i] = y[i] + alpha * y[k - i - 1];
            #   for (i = 0; i < k; i++) y[i] = z[i];
            #
            # Optimized in-place version:
            #   - We avoid the temporary z[0..N-1].
            #   - For each pair (i, j = k-i-1) with i < j, the new values are:
            #       y_i_new = y_i_old + alpha * y_j_old
            #       y_j_new = y_j_old + alpha * y_i_old
            #     which depends only on old y_i, y_j and matches z[] then copy.
            #   - For odd k, the middle element m = (k-1)/2 satisfies i == j and:
            #       y_m_new = y_m_old + alpha * y_m_old = y_m_old * (1 + alpha)
            #   - Each pair is disjoint, so iterations over p can be parallelized.
            #
            # Pairwise update for i<j:
            for p in [0, k/2):
                i = p
                j = k - p - 1
                # Only process when i < j to avoid double‑updating a pair
                if i < j:
                    t_i = y[i]
                    t_j = y[j]
                    y[i] = t_i + alpha * t_j
                    y[j] = t_j + alpha * t_i

            # Center element when k is odd (i == j case)
            if (k % 2 == 1):
                m = (k - 1) / 2
                y[m] = y[m] * (1.0 + alpha)

            # y[k] = alpha;
            y[k] = alpha

dependencies:
    # The body of the k loop is a true recurrence:
    # for each k >= 2, iteration k depends on completion of iteration k-1
    for k in [2, N):
        durbin(k-1) -> durbin(k)

optimization:
    # --- Arithmetic / memory simplifications --------------------------------
    # 1. Remove the temporary vector z[0..N-1] and fuse the "z" and "copy-back"
    #    loops into one in-place symmetric update on y[0..k-1] as described
    #    above in the computation section. This:
    #      - halves the memory footprint of temporaries in the kernel,
    #      - halves the memory traffic for y in that phase (one write instead
    #        of write-then-copy), and
    #      - reduces the number of loads from y by reusing t_i, t_j.
    #
    # 2. Keep r and y in contiguous 1D layouts as modeled above; they already
    #    have optimal spatial locality for the 1D access patterns.

    # --- Vectorization / blocking of the dot product ------------------------
    # The reduction   sum = sum_{i=0..k-1} r[k-i-1] * y[i]
    # is a dot product between y[0..k-1] (forward) and r[0..k-1] (backward).
    # It has no loop-carried dependencies beyond the reduction itself and is
    # suitable for SIMD and parallel reduction.
    #
    # V_SUM is a tunable SIMD width (e.g., 8 for AVX2 float, 16 for AVX-512).
    block(i, I_sum, I_TILE_SUM)   # I_TILE_SUM: tunable tile size for the sum, e.g., 256
    vectorize(i, V_SUM)           # vectorize the inner reduction over i
    # parallelize(i)               # optional: parallel reduction over i if N is large
    #                               # and a multi-core reduction is worthwhile

    # --- Optimization of the in-place pairwise update on y[0..k-1] ----------
    # For each k, the loop over p in [0, k/2) updates disjoint index pairs
    # (i, j = k-i-1). There are no cross-iteration dependencies, so we can
    # freely parallelize and vectorize over p.
    block(p, P_blk, P_TILE)       # tile p for cache / scheduling, tunable P_TILE
    vectorize(p, V_PAIR)          # SIMD over independent (i, j) pairs
    parallelize(p)                # multi-core parallelization over p

    # --- Loop ordering / hoisting ------------------------------------------
    # k must remain the outermost sequential loop because of the recurrence.
    # We make that explicit and let inner loops be ordered for locality/SIMD.
    hoist(k)                      # ensure k is the outer (sequential) loop

    # --- Scalar optimizations ----------------------------------------------
    # - Keep alpha, beta, sum in registers across inner loops.
    # - Strength reduction and CSE:
    #     * Reuse (1.0 - alpha * alpha) across uses within one k-iteration.
    # - Enable -O3, which together with the above structure allows the compiler
    #   to fully unroll small-k inner loops and aggressively vectorize both
    #   the reduction and the pairwise update.
--- END OF MODEL: durbin-04 ---

--- START OF MODEL: durbin-05 ---
# Optimized model for the Durbin kernel
# ------------------------------------
# This models the computation of kernel_durbin (including its dependence on r
# initialized by init_array), and applies algorithmic and loop-level
# optimizations while preserving the mathematical behavior.

domain:
    # Problem size (number of coefficients)
    i: dim in [0, N)              # element index within a vector
    k: dim in [0, N)              # outer Durbin iteration index

data:
    # Input auto-correlation sequence r[0..N-1]
    # Layout: single contiguous 1D array
    r[i]: in DATA_TYPE = (i) -> i

    # Reflection / prediction coefficients y[0..N-1]
    # Layout: single contiguous 1D array
    y[i]: inout DATA_TYPE = (i) -> i

parameters:
    N: size_t                     # logical length of r and y (matches length<'i'>)
    alpha: DATA_TYPE              # current reflection coefficient
    beta: DATA_TYPE               # scaling factor used in Durbin recursion
    sum: DATA_TYPE                # temporary accumulation for inner product
    VEC_LEN: int                  # tuning parameter for SIMD vector width (e.g., 4 or 8)
    UF_SUM: int                   # unroll factor for the sum loop over i
    UF_Y: int                     # unroll factor for the y-update loop over i

computation:
    # --- Initialization (init_array) ---
    # r[i] = N + 1 - i  (matches: r[i] = (num_t)(n + 1 - i) )
    init_r:
        for i in [0, N):
            r[i] = (DATA_TYPE)(N + 1 - i)

    # --- Durbin recursion kernel (optimized) ---
    durbin:
        # Initial step for k = 0:
        # y[0] = -r[0];
        # beta = 1.0;
        # alpha = -r[0];
        y[0] = -r[0]
        beta = (DATA_TYPE)1.0
        alpha = -r[0]

        # Main loop: for (k = 1; k < N; k++)
        # This loop is inherently sequential due to dependencies between iterations.
        durbin_k:
            for k in seq([1, N)):
                # beta = (1 - alpha * alpha) * beta;
                beta = ((DATA_TYPE)1.0 - alpha * alpha) * beta

                # sum = 0.0;
                # for (i = 0; i < k; i++)
                #     sum += r[k - i - 1] * y[i];
                #
                # This is a dot product between y[0..k-1] and r[0..k-1] reversed.
                durbin_sum:
                    sum = (DATA_TYPE)0.0
                    sum = sum(i in [0, k): r[k - 1 - i] * y[i])

                # alpha_new = - (r[k] + sum) / beta;
                alpha_new = -(r[k] + sum) / beta

                # Original code:
                #   for (i = 0; i < k; i++) z[i] = y[i] + alpha * y[k - i - 1];
                #   for (i = 0; i < k; i++) y[i] = z[i];
                #
                # Optimized variant:
                #   - eliminate the temporary array z[]
                #   - perform an *in-place* symmetric update on y[0..k-1]
                #     using pairs (i, j = k-1-i).
                #   - this preserves the final values exactly:
                #       y'[i] = y_old[i] + alpha_new * y_old[k-1-i]
                #       y'[k-1-i] = y_old[k-1-i] + alpha_new * y_old[i]
                #
                # We implement it with a half-range loop and, for odd k,
                # a single middle element. This reduces memory traffic and
                # removes the O(N) temporary storage z[0..N-1].
                y_update_pairs:
                    mid = (k - 1) / 2      # floor((k-1)/2)
                    # Process distinct symmetric pairs i < j = k-1-i
                    for i in [0, mid):
                        j = k - 1 - i

                        y_i_old = y[i]
                        y_j_old = y[j]

                        y[i] = y_i_old + alpha_new * y_j_old
                        y[j] = y_j_old + alpha_new * y_i_old

                y_update_middle:
                    # If k is odd, there is one middle index m = (k-1)/2
                    # with i == j; we must update it once:
                    #   y[m] = y_old[m] + alpha_new * y_old[m]
                    if (k % 2 == 1):
                        m = (k - 1) / 2
                        y_m_old = y[m]
                        y[m] = y_m_old + alpha_new * y_m_old

                # y[k] = alpha;  (using the updated alpha for this k)
                y_set_k:
                    y[k] = alpha_new

                # Prepare for next iteration
                alpha = alpha_new

dependencies:
    # k-iterations are strictly ordered:
    # - Each iteration k depends on alpha, beta, and y[0..k-1] computed at k-1.
    for k in [1, N):
        durbin_k(k-1) -> durbin_k(k)

    # Within each k, internal steps obey:
    #   beta_update -> durbin_sum -> alpha_update -> y_update_pairs -> y_update_middle -> y_set_k
    for k in [1, N):
        durbin_sum(k) -> alpha_new(k)
        alpha_new(k) -> y_update_pairs(k)
        y_update_pairs(k) -> y_update_middle(k)
        y_update_middle(k) -> y_set_k(k)

optimization:
    # 1. Preserve the required sequential dependence in k but exploit
    #    parallelism and SIMD within each k over the inner dimension i.

    # 1a) Parallelize the reduction for 'sum' over i with a proper reduction.
    #     This corresponds to replacing the serial accumulation in durbin_sum
    #     by a parallel tree-reduction on r[k-1-i] * y[i].
    parallelize(i)    # applied to the sum(i in [0, k): ...) in durbin_sum
    # Use a reduction-aware implementation (e.g., OpenMP reduction or TBB).

    # 1b) Parallelize the pairwise y update over i (distinct pairs only).
    #     Each (i, j) pair is independent at fixed k, so this is safe.
    parallelize(i)    # applied to the loop over i in y_update_pairs

    # 2. Enable SIMD vectorization on the inner i-dimension where data are
    #    contiguous (y[i] and most r accesses).
    vectorize(i, VEC_LEN)    # for both durbin_sum and y_update_pairs

    # 3. Loop unrolling to improve ILP and reduce branch/loop overhead.
    unroll(i, UF_SUM)        # unroll inner i-loop in durbin_sum
    unroll(i, UF_Y)          # unroll inner i-loop in y_update_pairs

    # 4. Strength-reduction and access pattern optimization in durbin_sum:
    #    - Treat r[k-1-i] as a reverse walk over a contiguous segment of r.
    #      This allows the implementation to maintain a running pointer
    #      that starts at base_r = &r[k-1] and decrements each step,
    #      reducing index arithmetic.
    #    - Combined with vectorize(i, ...), this supports efficient SIMD
    #      on a "gather" equivalent pattern or reversed contiguous loads.
    # (Expressed here as a comment; implemented at codegen level.)

    # 5. Memory usage optimization:
    #    - By eliminating the temporary vector z[0..N-1] and updating y[]
    #      in-place via symmetric pairs, we reduce extra memory by O(N)
    #      and cut the number of reads/writes to y[] by ~2× in the inner
    #      phase, improving cache usage and bandwidth efficiency.
    #    - This stays well within the requirement that added memory not
    #      exceed the original footprint by more than 50%.
--- END OF MODEL: durbin-05 ---

