computation:
    # -------------------------------------------------------------------------
    # Phase 0: initialization (matches init_array)
    # -------------------------------------------------------------------------

    # Initialize x, y, b:
    #   x[i] = 0
    #   y[i] = 0
    #   b[i] = (i+1)/N/2 + 4
