    # ==================================================================
    # 1. SPD construction B = A * A^T (dominant O(N^3) GEMM-like kernel)
    # ==================================================================

    # Block (tile) r, s, t to improve cache reuse of A and B.
    # After blocking:
    #   r  = R * Br + r_inner  with r_inner in [0, Br)
    #   s  = S * Bs + s_inner
    #   t  = T * Bt + t_inner
    block(r, R, Br)
    block(s, S, Bs)
    block(t, T, Bt)

    # Hoist tile indices so that iteration space is over tiles first,
    # then intra-tile indices. This exposes coarse-grain parallelism
    # and improves spatial locality inside tiles.
    hoist(R)
    hoist(S)
    hoist(T)

    # Parallelize SPD across tiles:
    #   - Different (R,S) tiles write disjoint sub-blocks B[r,s]
    #   - Reductions over t are local to each (r,s) and thus safe
    parallelize(R)          # primary outer parallel dimension
    parallelize(S)          # optionally also across S if enough cores

    # Vectorize the inner t-reduction within each (r,s) pair.
    # The compiler can implement this as a SIMD FMA reduction.
    vectorize(t, Vt)

    # ==================================================================
    # 2. LU factorization
    # ==================================================================

    # (Optional) strip-mining of i to improve cache behavior on very
    # large matrices while preserving the sequential row order:
    #   i = I_lu * Ti + i_inner, with outer I_lu still sequential.
    block(i, I_lu, Ti)
    hoist(I_lu)

    # For each fixed i, the lower-triangular loop (j < i) has loop-carried
    # dependencies in j and must remain sequential. The upper-triangular
    # loop (j >= i) has no dependencies between different j given that the
    # entire row i of L and all previous rows are fixed.
    #
    # We therefore parallelize only the upper-triangular j-loop:
    #
    #   parallelize_in(j, lu_factorization.lu_upper_row)
    #
    # where parallelize_in(DIM, LABEL) means: apply parallelization on
    # dimension DIM only to the loop nest labelled LABEL, leaving other
    # loops over DIM untouched.
    parallelize_in(j, lu_factorization.lu_upper_row)

    # In both L and U updates the inner k-loop is a pure reduction
    # (w -= A[i,k] * A[k,j]). Enable SIMD and moderate unrolling there.
    vectorize(k, K_lu_vec)
    unroll(k, factor = K_lu_vec)

